import pandas as pd
import datetime

df = pd.read_excel('DanhSachHoaDon.xlsx', sheet_name='Sheet1')
cols = list(df.columns)
df.columns = ['Mã hóa đơn','Thời gian','Mã KH','Khách hàng','Tổng tiền hàng','Giảm giá','Tổng sau giảm giá','Khách đã trả','Phương thức thanh toán','Trạng thái','Thời gian tạo','Ghi chú']

def parse_date(v):
    if isinstance(v, (int, float)):
        # Excel serial date: days since 1899-12-30
        return datetime.date(1899,12,30) + datetime.timedelta(days=int(v))
    s = str(v).strip()
    if not s:
        return pd.NaT
    for fmt in ('%d/%m/%Y', '%Y-%m-%d'):
        try:
            return pd.to_datetime(s, format=fmt).date()
        except Exception:
            pass
    return pd.to_datetime(s, errors='coerce').date()

df['d'] = df['Thời gian'].apply(parse_date)

nov = df[(df['d'] >= '2025-11-01') & (df['d'] <= '2025-11-30')]
